-- =====================================================================
-- Brokie price feed schedule. Run AFTER deploying the ingest-quotes function.
-- Replace YOUR-PROJECT-REF with the part of your Project URL before .supabase.co.
-- The shared secret is generated by the database itself (no copy/paste).
-- Pulls prices every 10 seconds (~260k calls/month, inside the free plan).
-- =====================================================================
create extension if not exists pg_cron;
create extension if not exists pg_net;

insert into public.brokie_private (key, value)
values ('ingest_url', 'https://YOUR-PROJECT-REF.supabase.co/functions/v1/ingest-quotes')
on conflict (key) do update set value = excluded.value;

select cron.unschedule(jobid) from cron.job where jobname = 'brokie-ingest-quotes';
select cron.schedule('brokie-ingest-quotes', '10 seconds', $$
  select net.http_post(
    url := (select value from public.brokie_private where key = 'ingest_url'),
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-cron-secret', (select value from public.brokie_private where key = 'cron_secret')),
    body := '{}'::jsonb,
    timeout_milliseconds := 8000)
$$);

-- Check it's working (wait ~30 s):
--   select market, price, quoted_at from public.quotes;
--   select status_code, content from net._http_response order by created desc limit 5;
